import { isNil } from 'lodash-es';
import React, { useContext, useLayoutEffect, useRef } from 'react';
import styled from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';

import { Icon } from './components/Icon.js';
import { defineTrendColors } from './functions/define-trend-colors.js';
import { defineTrendDirection } from './functions/define-trend-direction.js';
import { TrendProps } from './types/trend-props.js';
import { useMergeRefs } from '../../../../core/hooks/useMergeRefs.js';
import { uuidv4 } from '../../../../core/utils/uuidv4.js';
import { Flex } from '../../../../layouts-core/flex/Flex.js';
import { useFormatter } from '../../../core/hooks/useFormatter.js';
import { useThrottledResizeObserver } from '../../../core/hooks/useThrottledResizeObserver.js';
import { useGlobalFontSize } from '../../../single-value-grid/hooks/use-global-font-size.js';
import {
  FONT_HEIGHT_RATIO,
  TREND_FONT_CSS_TOKEN,
  TREND_FONT_SIZE,
} from '../../constants.js';
import { SingleValueContext } from '../../contexts/single-value.context.js';
import { useFontSizeForContainer } from '../../hooks/use-font-size-for-container.js';

interface StyledTrendProps {
  fontSize: number;
}

const StyledTrend = /* @__PURE__ */ styled(Flex).attrs<StyledTrendProps>(
  ({ fontSize }) => ({
    style: {
      [TREND_FONT_CSS_TOKEN]: fontSize,
    },
  }),
)<StyledTrendProps>({
  width: '100%',
  height: '100%',
  overflow: 'hidden',
});

const StyledChunk = /* @__PURE__ */ styled('div')({
  whiteSpace: 'nowrap',
  fontSize: `calc(${TREND_FONT_SIZE} * 1px)`,
  overflow: 'hidden',
});

const StyledValue = /* @__PURE__ */ styled('span')<{
  color: string;
  paddingLeft: string;
}>(({ color, paddingLeft }) => ({
  color,
  paddingLeft,
}));

const StyledLabel = /* @__PURE__ */ styled('span')<{ color: string }>(
  ({ color }) => ({
    color,
    marginLeft: 'min(10px, 1ch)',
  }),
);

export const Trend = (props: TrendProps) => {
  const {
    direction: directionProp,
    showIcon = true,
    value: valueProp,
    label,
    inverseTrend = 'none',
    colorsOverride,
    formatter: formatterProp,
  } = props;

  const { alignment } = useContext(SingleValueContext);

  const direction = defineTrendDirection(directionProp, valueProp);

  const [iconColor, valueColor] = defineTrendColors(
    direction,
    inverseTrend,
    colorsOverride,
  );

  const formatter = useFormatter(formatterProp);

  const formattedValue = !isNil(valueProp) ? formatter(valueProp) : '';

  const value = formattedValue.replace(' ', '');

  const ref = useRef<HTMLDivElement>();

  const { refCallback, width = 0, height = 0 } = useThrottledResizeObserver();

  const mergedRef = useMergeRefs([refCallback, ref]);

  const preferredFontSize = useFontSizeForContainer({
    container: { width, height: height * FONT_HEIGHT_RATIO },
    text: showIcon ? `00${value}0${label}` : `${value}0${label}`,
    element: ref.current,
  });

  const id = useRef<string>(uuidv4());
  const { updateTrendFontSize } = useGlobalFontSize();

  useLayoutEffect(() => {
    if (height && width) {
      updateTrendFontSize?.(id.current, preferredFontSize);
    }
  }, [height, width, preferredFontSize]);

  return (
    <StyledTrend
      ref={mergedRef}
      data-testid="single-value-trend"
      alignItems={'center'}
      justifyContent={alignment}
      gap={0}
      fontSize={preferredFontSize}
    >
      {showIcon && <Icon direction={direction} color={iconColor} />}
      <StyledChunk>
        <StyledValue color={valueColor} paddingLeft={showIcon ? '2ch' : '0'}>
          {value}
        </StyledValue>
        <StyledLabel color={Colors.Text.Neutral.Default}>{label}</StyledLabel>
      </StyledChunk>
    </StyledTrend>
  );
};

Trend['displayName'] = 'SingleValue.Trend';
